//GET同步
var _getSync = function(url,params,success,error){
    var paramsStr = "";
    $.each(params,function(key,value){
        paramsStr += key+"="+value +"&";
    });
    url += "?"+paramsStr.substr(0,paramsStr.length-1);
    $.ajax({
        url:url,
        type:"GET",
        async:false,
        success:function(res){
            if(success!=null&&success!=undefined &&(typeof success == "function" )){
                success(res);
            }
        },
        error:function(res){
            if(error!=null&&error!=undefined &&(typeof error == "function" )){
                error(res);
            }
        }
    });
};
//POST同步
var _postSync = function(url,params,success,error){
	$.ajax({
		url:url,
		type:"POST",
		async:false,
		data:params,
		success:function(res){
			if(success!=null&&success!=undefined &&(typeof success == "function" )){
				success(res);
			}
		},
		error:function(res){
			if(error!=null&&error!=undefined &&(typeof error == "function" )){
				error(res);
			}
		}
	});
};
